documents.source:
mutation setFeaturedWikiPages($serverName: String!, $wikiPageIds: [ID!]!) {
  setFeaturedWikiPages(serverName: $serverName, wikiPageIds: $wikiPageIds) {
    serverName
    featuredWikiPageIds
  }
}

mutation RefreshPlugins {
  refreshPlugins {
    id
    name
    Versions {
      version
    }
  }
}

mutation AllowPlugin($pluginId: ID!, $serverName: String!) {
  updateServerConfigs(
    where: {serverName: {eq: $serverName}}
    update: {AllowedPlugins: [{connect: [{where: {node: {id: {eq: $pluginId}}}}]}]}
  ) {
    serverConfigs {
      serverName
      AllowedPlugins {
        id
        name
      }
    }
  }
}

mutation DisallowPlugin($pluginId: ID!, $serverName: String!) {
  updateServerConfigs(
    where: {serverName: {eq: $serverName}}
    update: {AllowedPlugins: [{disconnect: [{where: {node: {id: {eq: $pluginId}}}}]}]}
  ) {
    serverConfigs {
      serverName
      AllowedPlugins {
        id
        name
      }
    }
  }
}

mutation InstallPluginVersion($pluginId: String!, $version: String!, $carrySettings: Boolean) {
  installPluginVersion(
    pluginId: $pluginId
    version: $version
    carrySettings: $carrySettings
  ) {
    plugin {
      id
      name
    }
    version
    scope
    enabled
    settingsJson
    carryOverReport
  }
}

mutation EnableServerPlugin($pluginId: String!, $version: String!, $enabled: Boolean!, $settingsJson: JSON) {
  enableServerPlugin(
    pluginId: $pluginId
    version: $version
    enabled: $enabled
    settingsJson: $settingsJson
  ) {
    plugin {
      id
      name
    }
    version
    scope
    enabled
    settingsJson
  }
}

mutation SetServerPluginSecret($pluginId: String!, $key: String!, $value: String!) {
  setServerPluginSecret(pluginId: $pluginId, key: $key, value: $value)
}

mutation CreatePluginPipelineCampaign($policyId: ID!, $concurrency: Int!, $rateLimitPerMinute: Int!) {
  createPluginPipelineCampaign(
    policyId: $policyId
    concurrency: $concurrency
    rateLimitPerMinute: $rateLimitPerMinute
  ) {
    id
    status
  }
}

mutation PausePluginPipelineCampaign($campaignId: ID!) {
  pausePluginPipelineCampaign(campaignId: $campaignId) {
    id
    status
    pausedAt
  }
}

mutation ResumePluginPipelineCampaign($campaignId: ID!) {
  resumePluginPipelineCampaign(campaignId: $campaignId) {
    id
    status
    pausedAt
  }
}

mutation UpdateModChannelRole($name: String!, $input: ModChannelRoleUpdateInput!) {
  updateModChannelRoles(where: {name: {eq: $name}}, update: $input) {
    modChannelRoles {
      name
      description
      channelUniqueName
      canHideComment
      canHideEvent
      canHideDiscussion
      canEditComments
      canEditDiscussions
      canEditEvents
      canGiveFeedback
      canOpenSupportTickets
      canCloseSupportTickets
      canReport
      canSuspendUser
    }
  }
}

mutation UpdateServerRole($name: String!, $input: ServerRoleUpdateInput!) {
  updateServerRoles(where: {name: {eq: $name}}, update: $input) {
    serverRoles {
      name
      description
      canCreateChannel
      canCreateDiscussion
      canCreateEvent
      canCreateComment
      canUpvoteDiscussion
      canUpvoteComment
      canUploadFile
      canGiveFeedback
    }
  }
}

mutation RemoveServerAdmin($serverName: String!, $username: String!) {
  updateServerConfigs(
    where: {serverName: {eq: $serverName}}
    update: {Admins: [{disconnect: [{where: {node: {username: {eq: $username}}}}]}]}
  ) {
    serverConfigs {
      serverName
      Admins {
        username
        displayName
      }
    }
  }
}

mutation RemoveServerModerator($serverName: String!, $displayName: String!) {
  updateServerConfigs(
    where: {serverName: {eq: $serverName}}
    update: {Moderators: [{disconnect: [{where: {node: {displayName: {eq: $displayName}}}}]}]}
  ) {
    serverConfigs {
      serverName
      Moderators {
        displayName
      }
    }
  }
}

mutation InviteServerAdmin($serverName: String!, $inviteeUsername: String!) {
  inviteServerAdmin(serverName: $serverName, inviteeUsername: $inviteeUsername)
}

mutation CancelInviteServerAdmin($serverName: String!, $inviteeUsername: String!) {
  cancelInviteServerAdmin(
    serverName: $serverName
    inviteeUsername: $inviteeUsername
  )
}

mutation AcceptServerAdminInvite($serverName: String!) {
  acceptServerAdminInvite(serverName: $serverName)
}

mutation InviteServerMod($serverName: String!, $inviteeUsername: String!) {
  inviteServerMod(serverName: $serverName, inviteeUsername: $inviteeUsername)
}

mutation CancelInviteServerMod($serverName: String!, $inviteeUsername: String!) {
  cancelInviteServerMod(
    serverName: $serverName
    inviteeUsername: $inviteeUsername
  )
}

mutation AcceptServerModInvite($serverName: String!) {
  acceptServerModInvite(serverName: $serverName)
}

mutation UpdateModServerRole($name: String!, $input: ModServerRoleUpdateInput!) {
  updateModServerRoles(where: {name: {eq: $name}}, update: $input) {
    modServerRoles {
      name
      description
      canLockChannel
      canHideComment
      canHideEvent
      canHideDiscussion
      canEditComments
      canEditDiscussions
      canEditEvents
      canGiveFeedback
      canOpenSupportTickets
      canCloseSupportTickets
      canReport
      canSuspendUser
    }
  }
}

mutation UpdatePluginPipelines($pipelines: [EventPipelineInput!]!) {
  updatePluginPipelines(pipelines: $pipelines)
}

query GetInstanceSetupStatus {
  getInstanceSetupStatus {
    auth {
      configured
      enabled
      requiredEnvVarsMissing
      setupUrl
      docsPath
    }
    mail {
      configured
      enabled
      requiredEnvVarsMissing
      setupUrl
      docsPath
    }
    maps {
      configured
      enabled
      requiredEnvVarsMissing
      setupUrl
      docsPath
    }
    geocoding {
      configured
      enabled
      requiredEnvVarsMissing
      setupUrl
      docsPath
    }
    uploads {
      configured
      enabled
      requiredEnvVarsMissing
      setupUrl
      docsPath
    }
    downloads {
      configured
      enabled
      requiredEnvVarsMissing
      setupUrl
      docsPath
    }
    events {
      configured
      enabled
      requiredEnvVarsMissing
      setupUrl
      docsPath
    }
    plugins {
      configured
      enabled
      requiredEnvVarsMissing
      setupUrl
      docsPath
    }
  }
}

query getServerSuspendedUsers($serverName: String!) {
  serverConfigs(where: {serverName: {eq: $serverName}}) {
    serverName
    SuspendedUsersConnection {
      aggregate {
        count {
          nodes
        }
      }
    }
    SuspendedUsers {
      id
      username
      createdAt
      suspendedUntil
      suspendedIndefinitely
      SuspendedUser {
        username
        displayName
        profilePicURL
        commentKarma
        discussionKarma
        createdAt
        isBot
      }
      RelatedIssue {
        id
        issueNumber
      }
    }
  }
}

query getServerSuspendedMods($serverName: String!) {
  serverConfigs(where: {serverName: {eq: $serverName}}) {
    serverName
    SuspendedModsConnection {
      aggregate {
        count {
          nodes
        }
      }
    }
    SuspendedMods {
      id
      modProfileName
      username
      createdAt
      suspendedUntil
      suspendedIndefinitely
      SuspendedMod {
        displayName
      }
      RelatedIssue {
        id
        issueNumber
      }
    }
  }
}

query getServerRules {
  serverConfigs {
    serverName
    rules
  }
}

query GetServerPluginSecrets($pluginId: String!) {
  getServerPluginSecrets(pluginId: $pluginId) {
    key
    status
    lastValidatedAt
    validationError
  }
}

query GetPluginConfigStatus($pluginId: String!, $version: String!, $scope: String) {
  getPluginConfigStatus(pluginId: $pluginId, version: $version, scope: $scope) {
    isFullyConfigured
    fields {
      key
      label
      scope
      kind
      required
      isSet
      isValid
      message
    }
  }
}

query PreviewPluginPipelineCampaign($policyId: ID!) {
  previewPluginPipelineCampaign(policyId: $policyId) {
    policyId
    eventType
    applicability
    enforcementBehavior
    affectedFileCount
    accessibleFileCount
    unavailableFileCount
    estimatedProviderRuns
  }
}

query GetPluginPipelineCampaignFailures($campaignId: ID!) {
  getPluginPipelineCampaignFailures(campaignId: $campaignId) {
    pipelineId
    targetId
    discussionId
    channelId
    status
    attemptNumber
  }
}

query GetPluginPipelines($serverName: String!) {
  serverConfigs(where: {serverName: {eq: $serverName}}) {
    serverName
    pluginPipelines
  }
}

mutation setMyBirthday($birthday: String!) {
  setMyBirthday(birthday: $birthday) {
    birthday
    meetsAccountMinimumAge
    mayAccessSensitiveContent
  }
}

query getAgePolicy {
  getAgePolicy {
    accountAgeGateEnabled
    minimumAccountAge
    sensitiveContentAgeGateEnabled
    minimumSensitiveContentAge
  }
}

query getDiscussionAgeGateCheck($discussionId: ID!) {
  getDiscussionAgeGateCheck(discussionId: $discussionId) {
    requiresAgeCheck
    status
    minimumAge
  }
}

mutation setChannelDiscussionFlairConfig($channelUniqueName: String!, $flairRequired: Boolean!, $flairs: [DiscussionFlairConfigInput!]!) {
  setChannelDiscussionFlairConfig(
    channelUniqueName: $channelUniqueName
    flairRequired: $flairRequired
    flairs: $flairs
  ) {
    channelUniqueName
    flairRequired
    flairs {
      id
      channelUniqueName
      displayName
      color
      order
      archived
    }
  }
}

mutation createChannel($createChannelInput: [ChannelCreateInput!]!) {
  createChannels(input: $createChannelInput) {
    channels {
      uniqueName
      description
      channelIconURL
      channelBannerURL
      Admins {
        username
      }
      createdAt
      Tags {
        text
      }
    }
  }
}

mutation updateChannel($where: ChannelWhere, $update: ChannelUpdateInput) {
  updateChannels(where: $where, update: $update) {
    channels {
      uniqueName
      displayName
      description
      channelIconURL
      channelBannerURL
      wikiEnabled
      eventsEnabled
      feedbackEnabled
      imageUploadsEnabled
      markdownImagesEnabled
      emojiEnabled
      downloadsEnabled
      allowedFileTypes
      Admins {
        username
      }
      createdAt
      Tags {
        text
      }
      WikiHomePage {
        id
        title
        body
        editReason
        slug
        createdAt
        updatedAt
        VersionAuthor {
          username
        }
        PastVersions(sort: [{createdAt: DESC}]) {
          id
          body
          editReason
          createdAt
          Author {
            username
          }
        }
      }
      rules
    }
  }
}

mutation permanentlyDeleteChannelBanner($channelUniqueName: String!, $imageUrl: String!) {
  permanentlyDeleteChannelBanner(
    channelUniqueName: $channelUniqueName
    imageUrl: $imageUrl
  ) {
    uniqueName
    channelBannerURL
  }
}

mutation setChannelIcon($channelUniqueName: String!, $imageUrl: String!) {
  setChannelIcon(channelUniqueName: $channelUniqueName, imageUrl: $imageUrl) {
    uniqueName
    channelIconURL
  }
}

mutation pinWikiPageToChannel($channelUniqueName: String!, $wikiPageId: ID!) {
  pinWikiPageToChannel(
    channelUniqueName: $channelUniqueName
    wikiPageId: $wikiPageId
  )
}

mutation unpinWikiPageFromChannel($channelUniqueName: String!, $wikiPageId: ID!) {
  unpinWikiPageFromChannel(
    channelUniqueName: $channelUniqueName
    wikiPageId: $wikiPageId
  )
}

mutation lockWikiPage($channelUniqueName: String!, $wikiPageId: ID!, $reason: String!) {
  lockWikiPage(
    channelUniqueName: $channelUniqueName
    wikiPageId: $wikiPageId
    reason: $reason
  ) {
    id
    locked
    lockedAt
    lockReason
    lockedByUsername
  }
}

mutation unlockWikiPage($channelUniqueName: String!, $wikiPageId: ID!) {
  unlockWikiPage(channelUniqueName: $channelUniqueName, wikiPageId: $wikiPageId) {
    id
    locked
    lockedAt
    lockReason
    lockedByUsername
  }
}

mutation becomeChannelAdmin($channelUniqueName: String!) {
  becomeForumAdmin(channelUniqueName: $channelUniqueName)
}

mutation UpdateChannelPluginPipelines($channelUniqueName: String!, $pipelines: [EventPipelineInput!]!) {
  updateChannelPluginPipelines(
    channelUniqueName: $channelUniqueName
    pipelines: $pipelines
  )
}

mutation UpdateChannelEnabledPlugins($channelUniqueName: String!, $enabledPlugins: [ChannelEnabledPluginsUpdateFieldInput!]!) {
  updateChannels(
    where: {uniqueName: {eq: $channelUniqueName}}
    update: {EnabledPlugins: $enabledPlugins}
  ) {
    channels {
      uniqueName
    }
  }
}

mutation reportChannel($channelUniqueName: String!, $reportText: String!, $selectedServerRules: [String!]!) {
  reportChannel(
    channelUniqueName: $channelUniqueName
    reportText: $reportText
    selectedServerRules: $selectedServerRules
  ) {
    id
    issueNumber
    relatedChannelUniqueName
  }
}

mutation lockChannel($channelUniqueName: String!, $reason: String!, $issueId: ID) {
  lockChannel(
    channelUniqueName: $channelUniqueName
    reason: $reason
    issueId: $issueId
  ) {
    uniqueName
    displayName
    locked
    lockedAt
    lockReason
    LockedBy {
      displayName
    }
  }
}

mutation unlockChannel($channelUniqueName: String!, $reason: String) {
  unlockChannel(channelUniqueName: $channelUniqueName, reason: $reason) {
    uniqueName
    displayName
    locked
    lockedAt
    lockReason
    LockedBy {
      displayName
    }
  }
}

mutation reportChannelImage($channelUniqueName: String!, $imageType: ChannelImageType!, $reportText: String!, $selectedServerRules: [String!]!) {
  reportChannelImage(
    channelUniqueName: $channelUniqueName
    imageType: $imageType
    reportText: $reportText
    selectedServerRules: $selectedServerRules
  ) {
    id
    issueNumber
  }
}

query getChannelNames($channelWhere: ChannelWhere) {
  channels(where: $channelWhere, limit: 10) {
    uniqueName
    displayName
    ...ChannelIconFields
    description
    eventsEnabled
  }
}

fragment ChannelIconFields on Channel {
  channelIconURL
}

query getChannelDiscussionFlairConfig($channelUniqueName: String!, $includeArchived: Boolean = false) {
  getChannelDiscussionFlairConfig(
    channelUniqueName: $channelUniqueName
    includeArchived: $includeArchived
  ) {
    channelUniqueName
    flairRequired
    flairs {
      id
      channelUniqueName
      displayName
      color
      order
      archived
    }
  }
}

query getWikiPage($channelUniqueName: String!, $slug: String!) {
  wikiPages(
    where: {channelUniqueName: {eq: $channelUniqueName}, slug: {eq: $slug}}
  ) {
    id
    title
    body
    editReason
    slug
    createdAt
    updatedAt
    locked
    lockedAt
    lockReason
    lockedByUsername
    VersionAuthor {
      username
    }
    ChildPages {
      id
      title
      editReason
      slug
      createdAt
      updatedAt
      locked
      lockedAt
      lockReason
      lockedByUsername
      VersionAuthor {
        username
      }
    }
    PastVersions(sort: [{createdAt: DESC}]) {
      id
      body
      editReason
      createdAt
      Author {
        username
      }
    }
  }
}

query getChannel($uniqueName: String!, $now: DateTime, $loggedInUsername: String) {
  channels(where: {uniqueName: {eq: $uniqueName}}) {
    uniqueName
    displayName
    description
    ...ChannelIconFields
    channelBannerURL
    isFavorited(username: $loggedInUsername)
    rules
    locked
    lockedAt
    lockReason
    LockedBy {
      displayName
    }
    wikiEnabled
    eventsEnabled
    feedbackEnabled
    imageUploadsEnabled
    markdownImagesEnabled
    emojiEnabled
    downloadsEnabled
    allowedFileTypes
    WikiHomePage {
      id
      title
      body
      editReason
      slug
      createdAt
      updatedAt
      VersionAuthor {
        username
      }
    }
    PinnedWikiPages(sort: [{updatedAt: DESC}]) {
      id
      title
      slug
      updatedAt
    }
    Tags {
      text
    }
    Admins {
      ...AuthorFields
    }
    Bots {
      username
      displayName
      botProfileId
      isDeprecated
      SuspensionsConnection(
        where: {node: {OR: [{suspendedIndefinitely: {eq: true}}, {suspendedUntil_GT: $now}]}}
      ) {
        aggregate {
          count {
            nodes
          }
        }
      }
    }
    Moderators {
      displayName
    }
    SuspendedMods {
      modProfileName
    }
    SuspendedUsers {
      username
    }
    DiscussionChannelsConnection(
      where: {node: {AND: [{NOT: {Discussion: null}}, {NOT: {Discussion: {hasDownload: {eq: true}}}}]}}
    ) {
      aggregate {
        count {
          nodes
        }
      }
    }
    IssuesConnection(where: {node: {isOpen: {eq: true}}}) {
      aggregate {
        count {
          nodes
        }
      }
    }
    EventChannelsConnection(
      where: {node: {NOT: {archived: {eq: true}, Event: null}, Event: {canceled: {eq: false}, endTime_GT: $now}}}
    ) {
      aggregate {
        count {
          nodes
        }
      }
    }
    DefaultModRole {
      canHideComment
      canHideEvent
      canHideDiscussion
      canDeleteWiki
      canEditComments
      canEditDiscussions
      canEditEvents
      canGiveFeedback
      canOpenSupportTickets
      canCloseSupportTickets
      canReport
      canSuspendUser
    }
    ElevatedModRole {
      canHideComment
      canHideEvent
      canHideDiscussion
      canDeleteWiki
      canEditComments
      canEditDiscussions
      canEditEvents
      canGiveFeedback
      canOpenSupportTickets
      canCloseSupportTickets
      canReport
      canSuspendUser
    }
    SuspendedModRole {
      canHideComment
      canHideEvent
      canHideDiscussion
      canDeleteWiki
      canEditComments
      canEditDiscussions
      canEditEvents
      canGiveFeedback
      canOpenSupportTickets
      canCloseSupportTickets
      canReport
      canSuspendUser
    }
    DefaultChannelRole {
      canCreateComment
      canCreateDiscussion
      canCreateEvent
      canUpdateChannel
      canUploadFile
      canUpvoteComment
      canUpvoteDiscussion
      channelUniqueName
    }
    ElevatedChannelRole {
      canCreateComment
      canCreateDiscussion
      canCreateEvent
      canUpdateChannel
      canUploadFile
      canUpvoteComment
      canUpvoteDiscussion
      channelUniqueName
    }
    SuspendedRole {
      canCreateComment
      canCreateDiscussion
      canCreateEvent
      canUpdateChannel
      canUploadFile
      canUpvoteComment
      canUpvoteDiscussion
      channelUniqueName
    }
    FilterGroups(sort: [{order: ASC}]) {
      id
      key
      displayName
      mode
      uploadSelection
      order
      options(sort: [{order: ASC}]) {
        id
        value
        displayName
        order
      }
    }
  }
}

fragment AuthorFields on User {
  username
  displayName
  profilePicURL
  createdAt
  discussionKarma
  commentKarma
}

fragment ChannelIconFields on Channel {
  channelIconURL
}

query getChannelRules($uniqueName: String!) {
  channels(where: {uniqueName: {eq: $uniqueName}}) {
    uniqueName
    rules
  }
}

query getEvents($uniqueName: String!, $now: DateTime) {
  events(
    limit: 4
    sort: [{startTime: ASC}]
    where: {AND: [{EventChannels_SOME: {channelUniqueName: {eq: $uniqueName}, archived: {eq: false}}}, {OR: [{canceled: {eq: false}, endTime_GT: $now}, {canceled: {eq: false}, startTime_LT: $now, endTime_GT: $now}]}]}
  ) {
    id
    title
    startTime
    endTime
    isAllDay
    virtualEventUrl
  }
}

query getChannelDownloadCount($uniqueName: String!) {
  channels(where: {uniqueName: {eq: $uniqueName}}) {
    uniqueName
    DiscussionChannelsConnection(
      where: {node: {AND: [{OR: [{archived: {eq: false}}, {archived: {eq: null}}]}, {NOT: {Discussion: null}}, {Discussion: {hasDownload: {eq: true}}}]}}
    ) {
      aggregate {
        count {
          nodes
        }
      }
    }
  }
}

query getSortedChannelsDiscussions($offset: Int, $limit: Int, $tags: [String], $searchInput: String, $loggedInUsername: String, $now: DateTime!) {
  getSortedChannels(
    offset: $offset
    limit: $limit
    tags: $tags
    searchInput: $searchInput
    countDownloads: false
  ) {
    channels {
      uniqueName
      displayName
      channelIconURL
      description
      isFavorited(username: $loggedInUsername)
      Tags {
        text
      }
      EventChannelsConnection(
        where: {node: {NOT: {archived: {eq: true}, Event: null}, Event: {canceled: {eq: false}, endTime_GT: $now}}}
      ) {
        aggregate {
          count {
            nodes
          }
        }
      }
      DiscussionChannelsConnection(
        where: {node: {AND: [{NOT: {archived: {eq: true}}}, {NOT: {Discussion: null}}, {NOT: {Discussion: {hasDownload: {eq: true}}}}]}}
      ) {
        aggregate {
          count {
            nodes
          }
        }
      }
    }
    aggregateChannelCount
  }
}

query getSortedChannelsDownloads($offset: Int, $limit: Int, $tags: [String], $searchInput: String) {
  getSortedChannels(
    offset: $offset
    limit: $limit
    tags: $tags
    searchInput: $searchInput
    countDownloads: true
  ) {
    channels {
      uniqueName
      DiscussionChannelsConnection(
        where: {node: {AND: [{NOT: {archived: {eq: true}}}, {NOT: {Discussion: null}}, {Discussion: {hasDownload: {eq: true}}}]}}
      ) {
        aggregate {
          count {
            nodes
          }
        }
      }
    }
  }
}

query getChannelContributions($channelUniqueName: String!, $startDate: String, $endDate: String, $year: Int, $limit: Int) {
  getChannelContributions(
    channelUniqueName: $channelUniqueName
    startDate: $startDate
    endDate: $endDate
    year: $year
    limit: $limit
  ) {
    username
    displayName
    profilePicURL
    totalContributions
    dayData {
      date
      count
      activities {
        id
        type
        description
        Comments {
          id
          text
          createdAt
          Channel {
            uniqueName
            displayName
            description
            channelIconURL
          }
          CommentAuthor {
            username
            profilePicURL
          }
          DiscussionChannel {
            id
            discussionId
            channelUniqueName
          }
        }
        Discussions {
          id
          title
          createdAt
          Author {
            username
            profilePicURL
          }
          DiscussionChannels {
            id
            channelUniqueName
            discussionId
          }
        }
      }
    }
  }
}

query GetUserFavoriteChannels($username: String!) {
  users(where: {username: {eq: $username}}) {
    username
    FavoriteChannels {
      displayName
      uniqueName
      channelIconURL
      eventsEnabled
    }
  }
}

query GetChannelPluginPipelines($channelUniqueName: String!) {
  channels(where: {uniqueName: {eq: $channelUniqueName}}) {
    uniqueName
    displayName
    pluginPipelines
    Admins {
      username
    }
  }
}

query GetChannelPluginSettings($channelUniqueName: String!, $now: DateTime) {
  channels(where: {uniqueName: {eq: $channelUniqueName}}) {
    uniqueName
    displayName
    Bots {
      username
      displayName
      botProfileId
      isDeprecated
      SuspensionsConnection(
        where: {node: {OR: [{suspendedIndefinitely: {eq: true}}, {suspendedUntil_GT: $now}]}}
      ) {
        aggregate {
          count {
            nodes
          }
        }
      }
    }
    EnabledPluginsConnection {
      edges {
        node {
          id
          version
          Plugin {
            id
            name
            displayName
            description
            tags
          }
        }
        properties {
          settingsJson
        }
      }
    }
  }
}

mutation CreateCollection($name: String!, $description: String, $collectionType: CollectionType!, $visibility: CollectionVisibility!, $updatedAt: DateTime!) {
  createCollections(
    input: [{name: $name, description: $description, collectionType: $collectionType, visibility: $visibility, itemOrder: [], updatedAt: $updatedAt}]
  ) {
    collections {
      id
      name
      description
      collectionType
      visibility
      itemCount
      createdAt
      updatedAt
    }
  }
}

