query getDiscussionFeedback($id: ID!, $limit: Int, $offset: Int, $loggedInModName: String!) {
  discussions(where: {id: {eq: $id}}) {
    id
    title
    body
    hasSensitiveContent
    Author {
      username
    }
    Album {
      id
      imageOrder
      Images(where: {NOT: {archived: {eq: true}, permanentlyRemoved: {eq: true}}}) {
        id
        url
        alt
        caption
        copyright
        Uploader {
          username
          displayName
        }
      }
    }
    DownloadableFiles(where: {NOT: {permanentlyRemoved: {eq: true}}}) {
      id
      fileName
      url
      downloadCountTotal
      downloadCountUnique
      attributionOverride
      supportPatreonUrl
      supportBuyMeACoffeeUrl
      supportKoFiUrl
      supportPayPalMeUrl
      scanStatus
      scanCheckedAt
      scanReason
      uploadedByUsername
    }
    CrosspostedDiscussion {
      ...CrosspostPreviewFields
    }
    FeedbackCommentsConnection {
      aggregate {
        count {
          nodes
        }
      }
    }
    FeedbackComments(limit: $limit, offset: $offset) {
      id
      text
      archived
      Channel {
        uniqueName
      }
      CommentAuthor {
        ... on ModerationProfile {
          createdAt
          displayName
        }
        ... on User {
          username
          createdAt
        }
      }
      createdAt
      FeedbackCommentsConnection(
        where: {node: {CommentAuthorConnection: {ModerationProfile: {node: {displayName: {eq: $loggedInModName}}}}}}
      ) {
        aggregate {
          count {
            nodes
          }
        }
      }
      FeedbackComments(
        where: {CommentAuthorConnection: {ModerationProfile: {node: {displayName: {eq: $loggedInModName}}}}}
      ) {
        id
      }
      GivesFeedbackOnDiscussion {
        id
      }
    }
  }
}

